class Solution {
public:
    string stringHash(string s, int k) {
        int n = s.size();
        string res = "";
        for (int i = 0; i < n; i += k) {
            int total = 0;
            for (int j = 0; j < k; ++j) {
                total += s[i + j] - 'a';
            }
            res += (char) ('a' + (total % 26));
        }
        return res;
    }
};

class Solution {
    public String stringHash(String s, int k) {
        int n = s.length();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i += k) {
            int total = 0;
            for (int j = 0; j < k; ++j) {
                total += s.charAt(i + j) - 'a';
            }
            sb.append((char) ('a' + (total % 26)));
        }
        return sb.toString();
    }
}

var stringHash = function(s, k) {
    const n = s.length;
    let res = "";
    for (let i = 0; i < n; i += k) {
        let total = 0;
        for (let j = 0; j < k; j++) {
            total += s.charCodeAt(i + j) - 97;
        }
        res += String.fromCharCode(97 + (total % 26));
    }
    return res;
};
